#pragma once
/**
 * @file NetworkStationIonoRunEnd.hpp
 * @brief Run-end reports of the station slant ionosphere: the adaptive process noise and the slant-ionosphere carry.
 *
 * The run-end reports defined in NetworkStationIonoRunEnd.cpp; each is a row of kNetworkRunEndReports
 * (filter/NetworkRunEnd.hpp).
 */

namespace GnssProcessor {

// ---- Run-end reports (card NOM step TD1b; generated by scripts/nom_td_cut.py) ----

struct NetworkRunEndView;

/**
 * @brief Run-end report: the adaptive ionosphere process noise.
 *
 * The adaptive ionosphere process noise: the monitor feeds summed over the stations, the
 * boosts and the largest multiplier, and a warning on zero feeds.
 *
 * Gate: returns 0 at once unless `config_.getNetworkConfig().adaptive_iono_q`.
 *
 * @param v The run at its end (filter/NetworkRunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkAdaptiveIonoQRunEnd(const NetworkRunEndView& v);

/**
 * @brief Run-end report: the slant-ionosphere carry.
 *
 * The slant-ionosphere carry (queue item 8b) at both coupling edges.
 *
 * Gate: prints under `config_.networkCarryIono()`.
 *
 * @param v The run at its end (filter/NetworkRunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkIonoCarryRunEnd(const NetworkRunEndView& v);

// ---- End of the run-end reports ----

} // namespace GnssProcessor
